export const BuildingFloorPlan: React.FC<{language?: Language}> = ({language = 'VN'}) => {
 const frame = useRef<HTMLIFrameElement>(null);
 const [height, setHeight] = useState(620);
 const documentHtml = useMemo(() => language === 'EN'
   ? EN_LABELS.reduce((html, [vi,en]) => html.split(vi).join(en), SECTION_DOCUMENT)
   : SECTION_DOCUMENT, [language]);
 useEffect(() => {
  const resize = (event: MessageEvent) => {
   if(event.source !== frame.current?.contentWindow || event.data?.type !== 'c10-section3-height') return;
   const value = Number(event.data.height);
   if(Number.isFinite(value)) setHeight(Math.min(2400,Math.max(360,Math.ceil(value)+2)));
  };
  window.addEventListener('message',resize);
  return () => window.removeEventListener('message',resize);
 },[]);
 return <div className="bg-white rounded-2xl border border-slate-200/80 shadow-2xs w-full min-w-0 overflow-hidden h-full">
  <iframe ref={frame} title={language === 'EN' ? 'C10 Section 3 floor progress' : 'C10 Mặt cắt 3 và tiến độ tầng'}
   srcDoc={documentHtml} sandbox="allow-scripts allow-same-origin allow-popups allow-popups-to-escape-sandbox"
   style={{width:'100%',height,border:0,display:'block'}} />
 </div>;
};
export default BuildingFloorPlan;
